{
  "items": [
    {
      "name": "MvPolynomial.degreeOf_le_totalDegree",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (f : MvPolynomial σ R) (i : σ) : MvPolynomial.degreeOf i f ≤ f.totalDegree",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_sum_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {ι : Type u_3} (i : σ) (s : Finset ι) (f : ι → MvPolynomial σ R) : MvPolynomial.degreeOf i (∑ j ∈ s, f j) ≤ s.sup fun j => MvPolynomial.degreeOf i (f j)",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_prod_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {ι : Type u_3} (i : σ) (s : Finset ι) (f : ι → MvPolynomial σ R) : MvPolynomial.degreeOf i (∏ j ∈ s, f j) ≤ ∑ j ∈ s, MvPolynomial.degreeOf i (f j)",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_X_self",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (j : σ) (f : MvPolynomial σ R) : MvPolynomial.degreeOf j (f * MvPolynomial.X j) ≤ MvPolynomial.degreeOf j f + 1",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (i : σ) (f g : MvPolynomial σ R) : MvPolynomial.degreeOf i (f * g) ≤ MvPolynomial.degreeOf i f + MvPolynomial.degreeOf i g",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_pow_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (i : σ) (p : MvPolynomial σ R) (n : ℕ) : MvPolynomial.degreeOf i (p ^ n) ≤ n * MvPolynomial.degreeOf i p",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.degreeOf_add_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (n : σ) (f g : MvPolynomial σ R) : MvPolynomial.degreeOf n (f + g) ≤ max (MvPolynomial.degreeOf n f) (MvPolynomial.degreeOf n g)",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.le_degreeOf_of_mem_support",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {p : MvPolynomial σ R} (i : σ) {s : σ →₀ ℕ} : s ∈ p.support → s i ≤ MvPolynomial.degreeOf i p",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    }
  ]
}
